7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * The duplicate block: because a household is keyed on (last name, postcode), an existing owner that
11	 * shares the new owner's {@link HouseholdNormalizer#id(String, String) household id} is the same
12	 * household, so the request is a household duplicate and is rejected with a 409 via
13	 * {@link DuplicateIdentityException}. Setting {@code sharesHousehold} acknowledges the shared
14	 * household and bypasses this block, so the new owner is created as a declared household member. Runs
15	 * after {@link AssignHousehold}, so the built owner already carries its household id.
16	 */
17	public class EnsureUniqueIdentity {
18	
19	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository)
20	            throws DuplicateIdentityException {
21	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
22	            return;
23	        }
24	        String householdId = owner.getHouseholdId();
25	        for (Owner existing : ownerRepository.findAll()) {
26	            if (HouseholdNormalizer.belongsTo(existing, householdId)) {
27	                throw new DuplicateIdentityException(householdId);
28	            }
29	        }
30	    }
31	}
