1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Flags a soft duplicate: a new owner that passed the duplicate block (see
10	 * {@link EnsureUniqueIdentity}) but still shares an existing owner's
11	 * {@link HouseholdNormalizer#id(String, String) household id} (same last name and postcode) while
12	 * giving a different telephone. Such a request is allowed but marked for follow-up: the built
13	 * {@link Owner} records {@code possibleDuplicate} true and {@code possibleDuplicateOf} the matching
14	 * owner's id (the earliest match when several exist). A <em>declared</em> household member (the
15	 * request set {@code sharesHousehold}) is never flagged — deliberately sharing a household is not a
16	 * suspected duplicate. When nothing matches, {@code possibleDuplicate} is false and
17	 * {@code possibleDuplicateOf} stays absent. Runs before {@link SaveOwner}, so the new owner is not
18	 * yet persisted and is never matched against itself. Mutates the built {@link Owner} in place.
19	 */
20	public class FlagPossibleDuplicate {
21	
22	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
23	        owner.setPossibleDuplicate(false);
24	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
25	            return;
26	        }
27	        String householdId = owner.getHouseholdId();
28	        Owner match = null;
29	        for (Owner existing : ownerRepository.findAll()) {
30	            if (HouseholdNormalizer.belongsTo(existing, householdId)
31	                    && !owner.getTelephone().equals(existing.getTelephone())) {
32	                if (match == null || existing.getId() < match.getId()) {
33	                    match = existing;
34	                }
35	            }
36	        }
37	        if (match != null) {
38	            owner.setPossibleDuplicate(true);
39	            owner.setPossibleDuplicateOf(match.getId());
40	        }
41	    }
42	}
